            if dist < min_dist:
                min_dist = dist
                threat = (ex, ey)
        if threat:
            # Move away from threat
            dx = -1 if threat[0] > x else 1 if threat[0] < x else 0
            dy = -1 if threat[1] > y else 1 if threat[1] < y else 0
        else:
            dx, dy = 0, 0

    # Bound dx, dy to -1, 0, 1
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))
