def choose_move(observation):
    gx, gy = observation['grid_width'], observation['grid_height']
    x, y = observation['self_position']
    res = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    opp_x, opp_y = observation.get('opponent_position', [x, y])
    score_self = observation['scores'][0]
    score_opp = observation['scores'][1]

    def move_towards(tx, ty):
        dx = 0 if tx == x else (1 if tx > x else -1)
        dy = 0 if ty == y else (1 if ty > y else -1)
        if (x + dx, y + dy) not in obstacles and 0 <= x + dx < gx and 0 <= y + dy < gy:
            return [dx, dy]
        # Try alternative directions if blocked
        for ndx, ndy in [(dx,0),(0,dy),(0,0)]:
            nx, ny = x + ndx, y + ndy
            if (nx, ny) not in obstacles and 0 <= nx < gx and 0 <= ny < gy:
                return [ndx, ndy]
        return [0,0]

    # Priority 1: Collect resources if available
    if res:
        tx, ty = res[0]
        return move_towards(tx, ty)

    # Priority 2: Move towards opponent if behind in score
    if score_self < score_opp:
        return move_towards(opp_x, opp_y)

    # Priority 3: Explore laterally to stay active
    for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
        nx, ny = x+dx,y+dy
        if (nx,ny) not in obstacles and 0 <= nx < gx and 0 <= ny < gy:
            return [dx, dy]

    # Default: stay in place
    return [0, 0]
